//! Data types of the API. They are serialised as JSON and mirrored to TypeScript by `ts-rs`
//! (`ui/src/lib/api/bindings.ts`, regenerated by `scripts/gen-bindings.sh`).

use notatnik_core::{BlockOp, TaskState};
use serde::{Deserialize, Serialize};
use ts_rs::TS;

/// Inline content of a block, ready to render without `innerHTML`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Inline {
    /// Plain text (raw HTML ends up here, shown literally).
    Text { text: String },
    /// `**bold**`
    Bold { children: Vec<Inline> },
    /// `*italic*`
    Italic { children: Vec<Inline> },
    /// `~~strike~~`
    Strike { children: Vec<Inline> },
    /// `==highlight==`
    Highlight { children: Vec<Inline> },
    /// `` `code` ``
    Code { text: String },
    /// External link (only http, https and mailto survive).
    Link { href: String, children: Vec<Inline> },
    /// Image; `local` images are relative paths below the graph (e.g. `../assets/x.png`).
    Image {
        src: String,
        alt: String,
        local: bool,
    },
    /// `[[page]]` / `[[page|label]]`
    PageRef {
        target: String,
        label: Option<Vec<Inline>>,
    },
    /// `#tag`
    Tag { target: String },
    /// `((id))`
    BlockRef { uid: String },
    /// `!((id))`
    BlockEmbed { uid: String },
    /// `![[page]]`
    PageEmbed { target: String },
    /// A line break inside a paragraph.
    SoftBreak,
    /// A hard line break.
    HardBreak,
}

/// Block-level content of a block.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Node {
    /// A paragraph.
    Paragraph { children: Vec<Inline> },
    /// `## Heading`
    Heading { level: u8, children: Vec<Inline> },
    /// A fenced or indented code block.
    CodeBlock { lang: Option<String>, code: String },
    /// A GFM table.
    Table {
        aligns: Vec<String>,
        header: Vec<Vec<Inline>>,
        rows: Vec<Vec<Vec<Inline>>>,
    },
    /// `> quote`
    Quote { children: Vec<Node> },
    /// A Markdown list inside a block.
    List {
        ordered: bool,
        items: Vec<Vec<Node>>,
    },
    /// `---`
    Rule,
    /// A fenced block with the language `query`.
    Query { text: String },
}

/// A block property for display.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct PropView {
    /// Key.
    pub key: String,
    /// Raw value text.
    pub raw: String,
    /// `text`, `number`, `bool`, `date`, `datetime`, `link` or `list`.
    pub kind: String,
    /// Page names, for link values.
    pub links: Vec<String>,
    /// Hidden in the rendered view (system or configured).
    pub hidden: bool,
}

/// Task data of a block.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct TaskView {
    /// State.
    pub state: TaskState,
    /// `scheduled::` as text.
    pub scheduled: Option<String>,
    /// `deadline::` as text.
    pub deadline: Option<String>,
    /// `high`, `medium` or `low`.
    pub priority: Option<String>,
    /// `repeat::` as text.
    pub repeat: Option<String>,
}

/// One block of a page.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct BlockView {
    /// Runtime ID, stable across edits and external changes within the session (P1.26).
    pub id: u32,
    /// Child-index path from the page root.
    pub path: Vec<u32>,
    /// Content hash of the block's own text (stale-edit guard).
    pub hash: String,
    /// `^id`, if the block has one.
    pub uid: Option<String>,
    /// Raw Markdown for the editor (first line, properties, continuation lines; no bullet, indentation or `^id`).
    pub text: String,
    /// Rendered content (without task marker, properties and `^id`).
    pub content: Vec<Node>,
    /// Task data.
    pub task: Option<TaskView>,
    /// Properties.
    pub props: Vec<PropView>,
    /// Collapsed on this device.
    pub collapsed: bool,
    /// Children.
    pub children: Vec<BlockView>,
}

/// Frontmatter for display.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct FrontmatterView {
    /// The YAML is valid.
    pub valid: bool,
    /// Title.
    pub title: Option<String>,
    /// Aliases.
    pub aliases: Vec<String>,
    /// Tags.
    pub tags: Vec<String>,
    /// Other properties.
    pub props: Vec<PropView>,
}

/// A parse problem to show.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct DiagnosticView {
    /// `error`, `warning` or `info`.
    pub severity: String,
    /// Message.
    pub message: String,
}

/// A page ready to render.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct PageView {
    /// Canonical page name.
    pub name: String,
    /// Display title (frontmatter title or the name).
    pub title: String,
    /// File path relative to the graph, `None` only for display of unknown pages.
    pub path: String,
    /// Whether the file exists (a missing page is shown empty and created on first content).
    pub exists: bool,
    /// Journal page.
    pub is_journal: bool,
    /// Hash of the file content; pass it back as `base_hash`. `None` while the file doesn't exist.
    pub hash: Option<String>,
    /// Frontmatter.
    pub frontmatter: Option<FrontmatterView>,
    /// Text before the first bullet.
    pub preamble: Option<BlockView>,
    /// Top-level blocks.
    pub blocks: Vec<BlockView>,
    /// Direct child pages in the namespace tree.
    pub child_pages: Vec<String>,
    /// Parse problems.
    pub diagnostics: Vec<DiagnosticView>,
}

/// Graph information.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct GraphInfo {
    /// Graph ID.
    pub id: String,
    /// Folder.
    pub root: String,
    /// Folder name.
    pub name: String,
    /// Nextcloud conflict copies.
    pub conflicts: Vec<String>,
    /// Config warnings from opening.
    pub warnings: Vec<String>,
    /// Week start (`monday` / `sunday`).
    pub week_start: String,
}

/// Result of an edit.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct ApplyResult {
    /// The page after the edit.
    pub page: PageView,
}

/// Full-text search hit.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct SearchHitView {
    /// `page` or `block`.
    pub kind: String,
    /// Page name.
    pub page: String,
    /// Block path, for block hits.
    pub path: Option<Vec<u32>>,
    /// Text.
    pub text: String,
    /// Byte ranges to highlight.
    pub highlights: Vec<Vec<u32>>,
}

/// Fuzzy title hit.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct TitleHit {
    /// Page name.
    pub name: String,
    /// The page has no file.
    pub is_virtual: bool,
}

/// A place that links to a page.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct BacklinkView {
    /// Source page.
    pub source_page: String,
    /// Block path, `None` for page-level links.
    pub block_path: Option<Vec<u32>>,
    /// The linking block (rendered), without its children.
    pub block: Option<BlockView>,
    /// Parent block texts, outermost first.
    pub breadcrumbs: Vec<String>,
    /// `page`, `tag` or `page_embed`.
    pub kind: String,
}

/// One node of the namespace tree.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct NamespaceEntry {
    /// Full page name.
    pub name: String,
    /// Last segment.
    pub leaf: String,
    /// No file behind it.
    pub is_virtual: bool,
    /// Has child pages.
    pub has_children: bool,
    /// Number of pages below (all depths).
    pub descendants: u32,
}

/// One day of the journals view.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct JournalDay {
    /// `YYYY-MM-DD`.
    pub date: String,
    /// Page name (same as `date`).
    pub name: String,
    /// The day has a file with content.
    pub exists: bool,
}

/// What a rename would do.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct RenamePlanView {
    /// Old name.
    pub old: String,
    /// New name.
    pub new: String,
    /// File moves `(from, to)`.
    pub file_moves: Vec<Vec<String>>,
    /// Files to rewrite with the number of references in each.
    pub edits: Vec<RenameEditView>,
    /// Warnings.
    pub warnings: Vec<String>,
}

/// One file touched by a rename.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct RenameEditView {
    /// Path.
    pub path: String,
    /// Replacements in the file.
    pub replacements: u32,
}

/// Result of an undo or redo.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct UndoResult {
    /// The page that was changed.
    pub page: PageView,
}

/// A conflict file shown next to its original.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
pub struct ConflictView {
    /// Path of the conflict copy.
    pub path: String,
    /// Its text.
    pub text: String,
    /// Page name of the original, if it can be derived.
    pub original: Option<String>,
    /// Text of the original.
    pub original_text: Option<String>,
}

